import React, { useState } from 'react';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

export default function LmsDashboard({ handleLogout }) {
  const [currentSubPage, setCurrentSubPage] = useState('Overview');

  const menuItems = [
    { name: 'Overview', icon: '📊' },
    { name: 'Students', icon: '👨‍🎓' },
    { name: 'Teachers & Classes', icon: '🏫' },
    { name: 'Reports', icon: '📋' },
    { name: 'Settings', icon: '⚙️' }
  ];

  const stats = { totalStudents: '1,250', totalTeachers: '45', activeClasses: '120', inactiveStudents: '25' };

  const growthData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May'],
    datasets: [{
      label: 'Enrollment Growth',
      data: [10, 32, 25, 48, 80],
      borderColor: '#15803d',
      backgroundColor: 'rgba(21, 128, 61, 0.1)',
      tension: 0.4,
      fill: true
    }]
  };

  return (
    <div style={{ display: 'flex', height: '100vh', width: '100vw', overflow: 'hidden', fontFamily: 'sans-serif' }}>
      
      {/* 🟢 වම් පැත්තේ සම්පූර්ණ උසටම යන කොළ පාට සයිඩ්බාර් එක (බිමටම වදින්න) */}
      <div style={{
        width: '260px',
        backgroundColor: '#15803d',
        color: '#ffffff',
        display: 'flex',
        flexDirection: 'column',
        padding: '25px 0',
        boxSizing: 'border-box',
        height: '100%',
        flexShrink: 0
      }}>
        <div>
          <div style={{ padding: '0 25px 20px 25px', borderBottom: '1px solid rgba(255,255,255,0.1)' }}>
            <h2 style={{ fontSize: '20px', fontWeight: 'bold', margin: 0 }}>Admin Panel</h2>
          </div>

          <nav style={{ marginTop: '25px', display: 'flex', flexDirection: 'column', gap: '8px', padding: '0 15px' }}>
            {menuItems.map((item) => {
              const isActive = currentSubPage === item.name;
              return (
                <button
                  key={item.name}
                  onClick={() => setCurrentSubPage(item.name)}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '14px',
                    width: '100%',
                    padding: '12px 15px',
                    backgroundColor: isActive ? 'rgba(0, 0, 0, 0.2)' : 'transparent',
                    color: '#ffffff',
                    border: 'none',
                    borderRadius: '8px',
                    cursor: 'pointer',
                    fontSize: '14px',
                    fontWeight: isActive ? '600' : '500',
                    textAlign: 'left'
                  }}
                >
                  <span>{item.icon}</span>
                  <span>{item.name}</span>
                </button>
              );
            })}
          </nav>
        </div>
      </div>

      {/* ⚪ දකුණු පැත්තේ කොටස */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', height: '100%', overflowY: 'auto' }}>
        
        {/* Top Navbar */}
        <div style={{ 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center', 
          padding: '18px 40px',
          borderBottom: '1px solid #e2e8f0',
          backgroundColor: '#ffffff',
          flexShrink: 0
        }}>
          <span style={{ fontWeight: '700', color: '#1e293b', fontSize: '15px' }}>Welcome, admin 👋</span>
          <button 
            onClick={handleLogout}
            style={{ 
              backgroundColor: '#dc2626', color: '#ffffff', border: 'none', padding: '8px 16px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px'
            }}
          >
            Logout
          </button>
        </div>

        {/* 📊 Dashboard Content Area */}
        <div style={{ padding: '40px', display: 'flex', flexDirection: 'column', gap: '30px', flex: '1 0 auto', backgroundColor: '#f8fafc' }}>
          
          {currentSubPage === 'Overview' && (
            <>
              {/* Stats Cards */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '25px' }}>
                {[
                  { t: 'Total Students', v: stats.totalStudents, i: '👨‍🎓' },
                  { t: 'Total Teachers', v: stats.totalTeachers, i: '👩‍🏫' },
                  { t: 'Active Classes', v: stats.activeClasses, i: '🏫' },
                  { t: 'Inactive Students', v: stats.inactiveStudents, i: '⚠️' }
                ].map((card, i) => (
                  <div key={i} style={{ background: '#ffffff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div>
                      <p style={{ color: '#64748b', fontSize: '13px', margin: '0 0 6px 0' }}>{card.t}</p>
                      <h2 style={{ margin: 0, color: '#1e293b', fontSize: '28px', fontWeight: '700' }}>{card.v}</h2>
                    </div>
                    <span style={{ fontSize: '28px' }}>{card.i}</span>
                  </div>
                ))}
              </div>

              {/* Chart Section */}
              <div style={{ display: 'grid', gridTemplateColumns: '2.5fr 1fr', gap: '25px' }}>
                <div style={{ background: '#ffffff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '20px' }}>
                    <h3 style={{ margin: 0, fontSize: '15px', color: '#1e293b', fontWeight: '600' }}>Enrollment Growth & Revenue Overview</h3>
                    <span style={{ backgroundColor: '#e0f2fe', color: '#0369a1', padding: '4px 12px', borderRadius: '20px', fontSize: '12px', fontWeight: '600' }}>Total Revenue: LKR 450,000</span>
                  </div>
                  <div style={{ height: '220px' }}><Line data={growthData} options={{ responsive: true, maintainAspectRatio: false }} /></div>
                </div>

                <div style={{ background: '#ffffff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
                  <h3 style={{ margin: '0 0 20px 0', fontSize: '15px', fontWeight: '600', color: '#1e293b' }}>Student Status At A-Glance</h3>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                    {[{ name: 'Ruwan Name', status: 'Active', bg: '#22c55e' }, { name: 'John Name', status: 'Active', bg: '#22c55e' }, { name: 'Sama Name', status: 'Inactive', bg: '#ef4444' }, { name: 'Ramn Name', status: 'Active', bg: '#22c55e' }].map((s, i) => (
                      <div key={i} style={{ display: 'flex', justifyContent: 'space-between', padding: '8px 0', borderBottom: '1px solid #f1f5f9', fontSize: '14px' }}>
                        <span>{s.name}</span>
                        <span style={{ backgroundColor: s.bg, color: '#fff', padding: '3px 8px', borderRadius: '6px', fontSize: '11px', fontWeight: 'bold' }}>{s.status}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* 📅 Schedule Table Box */}
              <div style={{ background: '#ffffff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
                <h3 style={{ margin: '0 0 20px 0', fontSize: '15px', fontWeight: '600', color: '#1e293b' }}>Upcoming Class Schedule</h3>
                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '14px' }}>
                  <thead>
                    <tr style={{ borderBottom: '2px solid #f1f5f9', textAlign: 'left', color: '#64748b' }}>
                      <th style={{ padding: '10px' }}>Time</th><th>Sun</th><th>Mon</th><th>Wed</th><th>Thu</th><th>Fri</th>
                    </tr>
                  </thead>
                  <tbody>
                    {[
                      { time: '10:00', sun: '', mon: 'Math 101', wed: '', thu: '', fri: '' },
                      { time: '11:00', sun: 'Wedneddiel', mon: '', wed: 'Science', thu: 'English Lit', fri: '' },
                      { time: '2:00', sun: '', mon: '', wed: '', thu: '', fri: 'History Class' }
                    ].map((row, i) => (
                      <tr key={i} style={{ borderBottom: '1px solid #f1f5f9' }}>
                        <td style={{ padding: '15px 10px', fontWeight: '600' }}>{row.time}</td>
                        <td>{row.sun && <span style={{ backgroundColor: '#15803d', color: '#fff', padding: '4px 10px', borderRadius: '6px', fontSize: '12px' }}>{row.sun}</span>}</td>
                        <td>{row.mon && <span style={{ backgroundColor: '#166534', color: '#fff', padding: '4px 10px', borderRadius: '6px', fontSize: '12px' }}>{row.mon}</span>}</td>
                        <td>{row.wed && <span style={{ backgroundColor: '#f59e0b', color: '#fff', padding: '4px 10px', borderRadius: '6px', fontSize: '12px' }}>{row.wed}</span>}</td>
                        <td>{row.thu && <span style={{ backgroundColor: '#10b981', color: '#fff', padding: '4px 10px', borderRadius: '6px', fontSize: '12px' }}>{row.thu}</span>}</td>
                        <td>{row.fri && <span style={{ backgroundColor: '#8b5cf6', color: '#fff', padding: '4px 10px', borderRadius: '6px', fontSize: '12px' }}>{row.fri}</span>}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {/* 🔘 බටන් 3 තීරුව - දැන් මේක සම්පූර්ණයෙන්ම එළියේ තනිවමයි පිහිටන්නේ (Figma එකේ වගේමයි) */}
              <div style={{ display: 'flex', gap: '15px', marginTop: '10px' }}>
                <button style={{ backgroundColor: '#15803d', color: 'white', border: 'none', padding: '12px 24px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' }}>
                  Manage Students
                </button>
                <button style={{ backgroundColor: '#ffffff', color: '#475569', border: '1px solid #cbd5e1', padding: '12px 24px', borderRadius: '8px', cursor: 'pointer', fontWeight: '600', fontSize: '13px' }}>
                  Manage Teachers
                </button>
                <button style={{ backgroundColor: '#ffffff', color: '#475569', border: '1px solid #cbd5e1', padding: '12px 24px', borderRadius: '8px', cursor: 'pointer', fontWeight: '600', fontSize: '13px' }}>
                  Create New Course
                </button>
              </div>
            </>
          )}

          {/* Subpages */}
          {currentSubPage === 'Students' && <div><h2>👨‍🎓 Student Management Section</h2></div>}
          {currentSubPage === 'Teachers & Classes' && <div><h2>🏫 Teachers & Classes Section</h2></div>}
          {currentSubPage === 'Reports' && <div><h2>📋 Academic Reports Section</h2></div>}
          {currentSubPage === 'Settings' && <div><h2>⚙️ System Settings Section</h2></div>}
        </div>

        {/* 🟦 Footer */}
        <footer style={{ backgroundColor: '#0a192f', color: '#ffffff', padding: '25px 40px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '13px', flexShrink: 0 }}>
          <div>
            <h4 style={{ margin: '0 0 5px 0', fontSize: '15px', fontWeight: 'bold' }}>AuraPen Saku</h4>
            <p style={{ margin: 0, opacity: 0.7, maxWidth: '400px', lineHeight: '1.4' }}>Sri Lanka's leading advanced educational institute, shaping the future of students through digital and physical learning.</p>
          </div>
          <div style={{ textAlign: 'right', display: 'flex', flexDirection: 'column', gap: '4px' }}>
            <span style={{ fontWeight: '600' }}>Contact Info</span>
            <span style={{ opacity: 0.7 }}>📍 Address: Opposite Bandaranayaka College, Mirigama</span>
            <span style={{ opacity: 0.7 }}>📞 Phone: +94 11 234 5678</span>
          </div>
        </footer>

      </div>
    </div>
  );
}
